StyleSheet:
/* Material Expressive: bold tonal colour, generous shapes that morph, a floating toolbar and springy motion. */
.bar { height: var(--p-bar-height); padding: 8px; gap: 4px; border-radius: 32px; offset: var(--p-float); box-shadow: 0px 6px 18px rgba(0,0,0,0.22);
       background: mix(var(--bar-bg), var(--accent-fill), var(--p-tonal)); }
.tab { height: 40px; padding: 0px 20px; border-radius: 20px; font-size: 14px; font-weight: semibold; indicator: none; stagger: var(--p-stagger); }
.tab:selected { color: var(--accent-fill-text); }
.menu { width: 324px; padding: 12px; gap: 4px; border-radius: 28px; offset: 10px; box-shadow: 0px 10px 28px rgba(0,0,0,0.26);
        background: mix(var(--menu-bg), var(--accent-fill), var(--p-tonal)); }
.menu-item { height: var(--p-row-height); padding: 0px 12px; border-radius: 26px; icon-size: 28px; font-size: 14px; stagger: var(--p-stagger); }
.button { min-height: 40px; padding: 8px 24px; border-radius: 20px; font-size: 14px; font-weight: semibold; background: var(--accent-soft); color: var(--accent); }
.button-primary { background: var(--accent-fill); color: var(--accent-fill-text); }
.input { min-height: 40px; padding: 8px 16px; border-radius: 14px; background: mix(var(--control-bg), var(--accent-fill), var(--p-tonal)); }
.card { padding: 22px 24px; gap: 10px; border-radius: var(--p-corner); stagger: var(--p-stagger); background: mix(var(--card-bg), var(--accent-fill), var(--p-tonal)); }
.window { border-radius: 16px; border-width: 0px; }
.titlebar { height: 44px; }
.sidebar { width: 216px; margin: 0px 8px 12px 12px; padding: 6px 0px; border-radius: 28px; background: mix(var(--sidebar-bg), var(--accent-fill), var(--p-tonal)); }
.sidebar-item { height: 46px; padding: 0px 18px; margin: 2px 0px; border-radius: 23px; font-size: 14px; }
.sidebar-item:selected { background: var(--accent-fill); color: var(--accent-fill-text); icon-color: var(--accent-fill-text); }
.toast { border-radius: 28px; border-width: 0px; background: mix(var(--popup-bg), var(--accent-fill), var(--p-tonal)); box-shadow: 0px 10px 26px rgba(0,0,0,0.28); }
